type LogoProps = {
  inverse?: boolean;
};

export function Logo({ inverse = false }: LogoProps) {
  return (
    <span className={`brand-lockup${inverse ? " brand-lockup--inverse" : ""}`}>
      <span className="brand-mark" aria-hidden="true">
        <span className="brand-mark__point" />
      </span>
      <span className="brand-name">
        <span className="brand-name__rama">RAMA</span>
      </span>
    </span>
  );
}

"use client";

import Link from "next/link";
import {
  ArrowUpRight,
  BarChart3,
  Building2,
  Command,
  LayoutDashboard,
  Menu,
  MessageSquareText,
  Search,
  Settings,
  ShieldCheck,
  X,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Logo } from "@/components/logo";
import type { StaffContext } from "@/lib/dashboard/dal";
import { OpsCommandCenter } from "@/components/dashboard/ops-command-center";
import { ProfileMenu } from "@/components/dashboard/profile-menu";

type DashboardShellProps = {
  staff: StaffContext;
  email: string | null;
  active: "overview" | "inventory" | "inquiries" | "analytics" | "settings";
  children: React.ReactNode;
};

const navigation = [
  { key: "overview", label: "Daily brief", href: "/dashboard", icon: LayoutDashboard },
  { key: "inventory", label: "Inventory", href: "/dashboard/inventory", icon: Building2 },
  { key: "inquiries", label: "Conversations", href: "/dashboard/inquiries", icon: MessageSquareText },
  { key: "analytics", label: "Analytics", href: "/dashboard/analytics", icon: BarChart3 },
] as const;

const settingsNavigation = { key: "settings", label: "Settings", href: "/dashboard/settings", icon: Settings } as const;
const allNavigation = [...navigation, settingsNavigation];

export function DashboardShell({ staff, email, active, children }: DashboardShellProps) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const mobileMenuButtonRef = useRef<HTMLButtonElement>(null);
  const mobileCloseButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setCommandOpen(true);
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  useEffect(() => {
    if (!mobileOpen) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const focusFrame = window.requestAnimationFrame(() => mobileCloseButtonRef.current?.focus());
    function closeOnEscape(event: KeyboardEvent) {
      if (event.key !== "Escape") return;
      setMobileOpen(false);
      window.requestAnimationFrame(() => mobileMenuButtonRef.current?.focus());
    }
    window.addEventListener("keydown", closeOnEscape);
    return () => {
      window.cancelAnimationFrame(focusFrame);
      window.removeEventListener("keydown", closeOnEscape);
      document.body.style.overflow = previousOverflow;
    };
  }, [mobileOpen]);

  function closeMobileNavigation() {
    setMobileOpen(false);
    window.requestAnimationFrame(() => mobileMenuButtonRef.current?.focus());
  }

  return (
    <div className="ops-shell">
      <a className="ops-skip-link" href="#operations-main">Skip to workspace</a>

      <aside className="ops-sidebar" aria-label="Rama operations navigation">
        <Link className="ops-sidebar-brand" href="/" target="_blank" rel="noopener noreferrer" aria-label="Open Rama public site in a new tab"><Logo /></Link>
        <div className="ops-sidebar-context"><span>Operations ledger</span><strong>{staff.organizationName}</strong></div>
        <nav className="ops-sidebar-nav" aria-label="Operations">
          {navigation.map((item) => {
            const Icon = item.icon;
            const selected = active === item.key;
            return <Link key={item.key} aria-current={selected ? "page" : undefined} href={item.href}><Icon aria-hidden="true" /><span>{item.label}</span></Link>;
          })}
        </nav>
        <div className="ops-sidebar-foot">
          <nav className="ops-sidebar-utility" aria-label="Workspace settings">
            <Link aria-current={active === settingsNavigation.key ? "page" : undefined} href={settingsNavigation.href}><Settings aria-hidden="true" /><span>Settings</span></Link>
          </nav>
          <div className="ops-policy-note"><ShieldCheck aria-hidden="true" /><span><strong>Governed workspace</strong><small>Source and role controls active</small></span></div>
          <Link className="ops-public-link" href="/" target="_blank" rel="noopener noreferrer">Buyer experience <span>New tab</span><ArrowUpRight aria-hidden="true" /></Link>
        </div>
      </aside>

      {mobileOpen ? <button className="ops-mobile-scrim" type="button" aria-label="Dismiss navigation" onClick={closeMobileNavigation} /> : null}
      <aside id="operations-mobile-navigation" className="ops-mobile-drawer" data-open={mobileOpen} aria-hidden={!mobileOpen} inert={!mobileOpen}>
        <div className="ops-mobile-drawer-head"><Logo /><button ref={mobileCloseButtonRef} type="button" aria-label="Close navigation" onClick={closeMobileNavigation}><X aria-hidden="true" /></button></div>
        <nav aria-label="Mobile operations">
          {navigation.map((item) => { const Icon = item.icon; return <Link key={item.key} aria-current={active === item.key ? "page" : undefined} href={item.href} onClick={() => setMobileOpen(false)}><Icon aria-hidden="true" />{item.label}</Link>; })}
          <Link aria-current={active === "settings" ? "page" : undefined} href="/dashboard/settings" onClick={() => setMobileOpen(false)}><Settings aria-hidden="true" />Settings</Link>
          <Link href="/" target="_blank" rel="noopener noreferrer" onClick={() => setMobileOpen(false)}><ArrowUpRight aria-hidden="true" />Buyer experience <small>New tab</small></Link>
        </nav>
      </aside>

      <div className="ops-workspace">
        <header className="ops-command-bar">
          <button ref={mobileMenuButtonRef} className="ops-menu-trigger" type="button" aria-label="Open navigation" aria-controls="operations-mobile-navigation" aria-expanded={mobileOpen} onClick={() => setMobileOpen(true)}><Menu aria-hidden="true" /></button>
          <div className="ops-breadcrumb"><span>Rama</span><strong>{allNavigation.find((item) => item.key === active)?.label}</strong></div>
          <button className="ops-command-trigger" type="button" onClick={() => setCommandOpen(true)}><Search aria-hidden="true" /><span>Ask Rama or search the workspace</span><kbd><Command aria-hidden="true" />K</kbd></button>
          <ProfileMenu staff={staff} email={email} />
        </header>

        <main id="operations-main" className="ops-main">{children}</main>
      </div>

      <nav className="ops-bottom-nav" aria-label="Mobile operations">
        {navigation.map((item) => { const Icon = item.icon; return <Link key={item.key} aria-current={active === item.key ? "page" : undefined} href={item.href}><Icon aria-hidden="true" /><span>{item.label === "Daily brief" ? "Brief" : item.label}</span></Link>; })}
        <button type="button" onClick={() => setCommandOpen(true)}><Search aria-hidden="true" /><span>Ask Rama</span></button>
      </nav>

      <OpsCommandCenter isOpen={commandOpen} onOpenChange={setCommandOpen} />
    </div>
  );
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { ArrowRight, BarChart3, Building2, Command, LayoutDashboard, MessageSquareText, Search, Settings, ShieldCheck, Sparkles, TriangleAlert, X } from "lucide-react";
import { Dialog, Modal, ModalOverlay } from "react-aria-components";
import { type FormEvent, useMemo, useState } from "react";
import {
  rankDashboardCommands,
  type DashboardCommand,
} from "@/lib/dashboard/commands";

type CommandWithIcon = DashboardCommand & { icon: typeof LayoutDashboard };

const commands: readonly CommandWithIcon[] = [
  { id: "brief", label: "Open the daily brief", detail: "Review action queues and catalog readiness", href: "/dashboard", icon: LayoutDashboard, terms: "overview daily brief readiness operations" },
  { id: "inventory", label: "Review governed inventory", detail: "Search, filter, and inspect catalog records", href: "/dashboard/inventory", icon: Building2, terms: "property properties inventory catalog residence residences listing listings" },
  { id: "refresh", label: "Find listings needing a refresh", detail: "Open inventory filtered to stale or missing sources", href: "/dashboard/inventory?health=attention", icon: TriangleAlert, terms: "source refresh stale missing health evidence expired listings records" },
  { id: "review", label: "Review publication queue", detail: "Open records waiting for editorial approval", href: "/dashboard/inventory?status=in_review", icon: ShieldCheck, terms: "publication publish review approval waiting records" },
  { id: "conversations", label: "Open buyer conversations", detail: "Continue consented advisor handoffs", href: "/dashboard/inquiries", icon: MessageSquareText, terms: "buyer inquiry inquiries conversation conversations follow up lead leads" },
  { id: "reply", label: "Find conversations needing a reply", detail: "Open new buyer handoffs awaiting an advisor", href: "/dashboard/inquiries?view=needs_reply", icon: MessageSquareText, terms: "buyer inquiry conversations reply new advisor follow up" },
  { id: "analytics", label: "Open analytics workspace", detail: "Inspect traffic, discovery patterns, and conversion telemetry", href: "/dashboard/analytics", icon: BarChart3, terms: "analytics traffic pageviews visitors metrics telemetry posthog conversion funnel" },
  { id: "settings", label: "Open workspace settings", detail: "Manage profile, security, and Rama governance", href: "/dashboard/settings", icon: Settings, terms: "settings profile avatar password security workspace rama ai" },
];

const suggestions = [
  { label: "Which listings need a source refresh?", href: "/dashboard/inventory?health=attention" },
  { label: "Show records waiting for publication review", href: "/dashboard/inventory?status=in_review" },
  { label: "Which buyer conversations need a reply?", href: "/dashboard/inquiries?view=needs_reply" },
  { label: "Inspect buyer discovery and traffic analytics", href: "/dashboard/analytics" },
] as const;

export function OpsCommandCenter({ isOpen, onOpenChange }: { isOpen: boolean; onOpenChange: (open: boolean) => void }) {
  const router = useRouter();
  const [query, setQuery] = useState("");
  const matches = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return [...commands];
    return rankDashboardCommands(commands, normalized) as CommandWithIcon[];
  }, [query]);

  function changeOpenState(open: boolean) {
    if (!open) setQuery("");
    onOpenChange(open);
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (matches[0]) { changeOpenState(false); router.push(matches[0].href); }
  }

  return <ModalOverlay isOpen={isOpen} isDismissable onOpenChange={changeOpenState} className="ops-command-overlay">
    <Modal className="ops-command-modal">
      <Dialog aria-label="Ask Rama operations command" className="ops-command-dialog">
        <header><div><span><Sparkles aria-hidden="true" />Ask Rama</span><h2>Find the next operational move.</h2></div><button type="button" aria-label="Close command center" onClick={() => changeOpenState(false)}><X aria-hidden="true" /></button></header>
        <form onSubmit={submit} className="ops-command-search"><Search aria-hidden="true" /><label><span className="sr-only">Search the CRM</span><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search inventory, conversations, or a task…" /></label><kbd><Command aria-hidden="true" />K</kbd></form>
        <div className="ops-command-body">
          <section aria-labelledby="command-results"><p id="command-results">Workspace</p><div className="ops-command-results">{matches.length ? matches.map((item) => { const Icon = item.icon; return <Link key={item.href} href={item.href} onClick={() => changeOpenState(false)}><Icon aria-hidden="true" /><span><strong>{item.label}</strong><small>{item.detail}</small></span><ArrowRight aria-hidden="true" /></Link>; }) : <div className="ops-command-empty"><strong>No workspace shortcut matches.</strong><span>Try “inventory,” “publication,” or “conversations.”</span></div>}</div></section>
          {!query ? <section aria-labelledby="rama-suggestions"><p id="rama-suggestions">Suggested operational questions</p><div className="ops-command-suggestions">{suggestions.map((suggestion) => <Link key={suggestion.href} href={suggestion.href} onClick={() => changeOpenState(false)}>{suggestion.label}<ArrowRight aria-hidden="true" /></Link>)}</div></section> : null}
        </div>
        <footer><span><ShieldCheck aria-hidden="true" />Role-aware workspace search</span><small>Operational AI answers will remain source-bound and require confirmation before any write.</small></footer>
      </Dialog>
    </Modal>
  </ModalOverlay>;
}

import type { LucideIcon } from "lucide-react";

export function PageHeader({ eyebrow, title, description, action, marker: Marker }: { eyebrow: string; title: string; description: string; action?: React.ReactNode; marker?: LucideIcon }) {
  return <header className="ops-page-header"><div className="ops-page-title">{Marker ? <Marker aria-hidden="true" /> : null}<div><p>{eyebrow}</p><h1>{title}</h1></div></div><div className="ops-page-summary"><p>{description}</p>{action}</div></header>;
}

export function SectionHeader({ id, eyebrow, title, meta, action }: { id?: string; eyebrow: string; title: string; meta?: string; action?: React.ReactNode }) {
  return <header id={id} className="ops-section-header"><div><p>{eyebrow}</p><h2>{title}</h2>{meta ? <span>{meta}</span> : null}</div>{action}</header>;
}

"use client";

import {
  ArrowUpRight,
  Building2,
  ChevronDown,
  LogOut,
  Settings,
  ShieldCheck,
  UserRound,
} from "lucide-react";
import { useState, useTransition } from "react";
import { signOutAction } from "@/app/auth/actions";
import { ProfileAvatar } from "@/components/dashboard/profile-avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { StaffContext } from "@/lib/dashboard/dal";

type ProfileMenuProps = {
  staff: StaffContext;
  email: string | null;
};

export function ProfileMenu({ staff, email }: ProfileMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [signingOut, startSignOut] = useTransition();
  const role = staff.role.replaceAll("_", " ");

  return (
    <DropdownMenuTrigger isOpen={isOpen} onOpenChange={setIsOpen}>
      <Button
        className="ops-profile-trigger"
        variant="ghost"
        aria-label={`Open profile menu for ${staff.fullName}`}
      >
        <ProfileAvatar fullName={staff.fullName} email={email} avatarUrl={staff.avatarUrl} />
        <span className="ops-profile-trigger-copy">
          <strong>{staff.fullName}</strong>
          <small>{role} · account</small>
        </span>
        <ChevronDown aria-hidden="true" />
      </Button>

      <DropdownMenu placement="bottom end" offset={8} className="ops-profile-menu">
        <DropdownMenuLabel className="ops-profile-menu-identity">
          <ProfileAvatar
            fullName={staff.fullName}
            email={email}
            avatarUrl={staff.avatarUrl}
            size="lg"
          />
          <span>
            <strong>{staff.fullName}</strong>
            <small>{email || "Verified staff account"}</small>
            <em>{staff.organizationName} · {role}</em>
          </span>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        <DropdownMenuItem href="/dashboard/settings#profile" textValue="Profile settings">
          <UserRound aria-hidden="true" />
          Profile and photo
        </DropdownMenuItem>
        <DropdownMenuItem href="/dashboard/settings#workspace" textValue="Workspace settings">
          <Building2 aria-hidden="true" />
          Workspace settings
        </DropdownMenuItem>
        <DropdownMenuItem href="/dashboard/settings#security" textValue="Security settings">
          <ShieldCheck aria-hidden="true" />
          Security and sessions
        </DropdownMenuItem>
        <DropdownMenuItem href="/dashboard/settings" textValue="All settings">
          <Settings aria-hidden="true" />
          All settings
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          href="/"
          target="_blank"
          rel="noopener noreferrer"
          textValue="Open buyer experience in a new tab"
        >
          <ArrowUpRight aria-hidden="true" />
          Open buyer experience
          <span className="ops-profile-menu-meta">New tab</span>
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant="destructive"
          textValue="Sign out"
          isDisabled={signingOut}
          onAction={() => {
            setIsOpen(false);
            startSignOut(() => signOutAction());
          }}
        >
          <LogOut aria-hidden="true" />
          {signingOut ? "Signing out…" : "Sign out"}
        </DropdownMenuItem>
      </DropdownMenu>
    </DropdownMenuTrigger>
  );
}

import type { CSSProperties } from "react";
import { profileInitials } from "@/lib/dashboard/profile";

type ProfileAvatarProps = {
  fullName: string | null;
  email: string | null;
  avatarUrl: string | null;
  size?: "sm" | "md" | "lg";
};

export function ProfileAvatar({ fullName, email, avatarUrl, size = "md" }: ProfileAvatarProps) {
  const style = avatarUrl
    ? ({ "--profile-avatar": `url("${avatarUrl}")` } as CSSProperties)
    : undefined;

  return (
    <span
      className="ops-profile-avatar"
      data-size={size}
      data-has-image={Boolean(avatarUrl)}
      style={style}
      aria-hidden="true"
    >
      {profileInitials(fullName, email)}
    </span>
  );
}

"use client";

import { Camera, Check, KeyRound, LogOut, Trash2, Upload } from "lucide-react";
import { useActionState, useEffect, useRef, useState } from "react";
import { useFormStatus } from "react-dom";
import { signOutAction } from "@/app/auth/actions";
import {
  removeAvatarAction,
  updatePasswordAction,
  updateProfileAction,
  uploadAvatarAction,
} from "@/app/dashboard/settings/actions";
import { ProfileAvatar } from "@/components/dashboard/profile-avatar";
import { initialActionState } from "@/lib/dashboard/validation";
import type { StaffContext } from "@/lib/dashboard/dal";

type ProfileSettingsFormProps = {
  staff: StaffContext;
  email: string | null;
  children?: React.ReactNode;
};

function FormMessage({ state }: { state: typeof initialActionState }) {
  if (!state.message) return null;
  return <p className="ops-settings-message" data-status={state.status} role="status">{state.message}</p>;
}

function SignOutButton() {
  const { pending } = useFormStatus();
  return (
    <button className="ops-settings-remove" type="submit" disabled={pending}>
      <LogOut aria-hidden="true" />{pending ? "Signing out…" : "Sign out of this device"}
    </button>
  );
}

export function ProfileSettingsForm({ staff, email, children }: ProfileSettingsFormProps) {
  const [profileState, profileAction, profilePending] = useActionState(updateProfileAction, initialActionState);
  const [avatarState, avatarAction, avatarPending] = useActionState(uploadAvatarAction, initialActionState);
  const [removeState, removeAction, removePending] = useActionState(removeAvatarAction, initialActionState);
  const [passwordState, passwordAction, passwordPending] = useActionState(updatePasswordAction, initialActionState);
  const [preview, setPreview] = useState<string | null>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);
  const passwordFormRef = useRef<HTMLFormElement>(null);

  useEffect(() => () => {
    if (preview) URL.revokeObjectURL(preview);
  }, [preview]);

  useEffect(() => {
    if (passwordState.status === "success") passwordFormRef.current?.reset();
  }, [passwordState.status]);

  function previewAvatar(file: File | undefined) {
    if (preview) URL.revokeObjectURL(preview);
    setPreview(file ? URL.createObjectURL(file) : null);
  }

  return (
    <>
      <section id="profile" className="ops-settings-section" aria-labelledby="profile-heading">
        <header><span>01</span><div><p>Personal profile</p><h2 id="profile-heading">How you appear in the workspace</h2></div></header>
        <div className="ops-settings-avatar-row" id="avatar">
          <ProfileAvatar
            fullName={staff.fullName}
            email={email}
            avatarUrl={preview || staff.avatarUrl}
            size="lg"
          />
          <div><strong>Profile photo</strong><small>JPG, PNG, or WebP. Maximum 2 MB.</small></div>
          <form action={avatarAction} className="ops-settings-avatar-form">
            <input
              ref={avatarInputRef}
              className="sr-only"
              type="file"
              name="avatar"
              accept="image/jpeg,image/png,image/webp"
              aria-hidden="true"
              tabIndex={-1}
              required
              onChange={(event) => previewAvatar(event.currentTarget.files?.[0])}
            />
            <button className="ops-file-control" type="button" onClick={() => avatarInputRef.current?.click()}>
              <Camera aria-hidden="true" />
              <span>{preview ? "Choose another" : "Choose image"}</span>
            </button>
            <button type="submit" disabled={avatarPending || !preview}><Upload aria-hidden="true" />{avatarPending ? "Uploading…" : "Upload"}</button>
          </form>
          {staff.avatarPath ? <form action={removeAction}><button className="ops-settings-remove" type="submit" disabled={removePending}><Trash2 aria-hidden="true" />{removePending ? "Removing…" : "Remove"}</button></form> : null}
        </div>
        <FormMessage state={avatarState} />
        <FormMessage state={removeState} />

        <form action={profileAction} className="ops-settings-form">
          <label>
            Full name
            <input name="fullName" defaultValue={staff.fullName} required minLength={2} maxLength={120} aria-invalid={Boolean(profileState.fieldErrors?.fullName)} />
            {profileState.fieldErrors?.fullName ? <small>{profileState.fieldErrors.fullName}</small> : null}
          </label>
          <label>
            Email
            <input value={email || "Verified Supabase account"} readOnly aria-describedby="email-note" />
            <small id="email-note">Email changes require a verified Supabase confirmation.</small>
          </label>
          <label>
            Timezone
            <select name="timezone" defaultValue={staff.timezone} aria-invalid={Boolean(profileState.fieldErrors?.timezone)}>
              <option value="Asia/Dubai">Dubai · Gulf Standard Time</option>
              <option value="Etc/UTC">UTC</option>
              <option value="Europe/London">London</option>
              <option value="America/New_York">New York</option>
            </select>
            {profileState.fieldErrors?.timezone ? <small>{profileState.fieldErrors.timezone}</small> : null}
          </label>
          <label>
            Interface language
            <select name="locale" defaultValue={staff.locale} aria-invalid={Boolean(profileState.fieldErrors?.locale)}>
              <option value="en">English</option>
              <option value="ar" disabled>Arabic · coming later</option>
            </select>
            {profileState.fieldErrors?.locale ? <small>{profileState.fieldErrors.locale}</small> : null}
          </label>
          <div className="ops-settings-form-footer">
            <span>Profile preferences are private to this account.</span>
            <button type="submit" disabled={profilePending}><Check aria-hidden="true" />{profilePending ? "Saving…" : "Save profile"}</button>
          </div>
        </form>
        <FormMessage state={profileState} />
      </section>

      {children}

      <section id="security" className="ops-settings-section" aria-labelledby="security-heading">
        <header><span>04</span><div><p>Account security</p><h2 id="security-heading">Password and verified identity</h2></div></header>
        <form ref={passwordFormRef} action={passwordAction} className="ops-settings-form ops-settings-form--security">
          <label>New password<input name="password" type="password" autoComplete="new-password" minLength={12} required aria-invalid={Boolean(passwordState.fieldErrors?.password)} />{passwordState.fieldErrors?.password ? <small>{passwordState.fieldErrors.password}</small> : null}</label>
          <label>Confirm password<input name="confirmation" type="password" autoComplete="new-password" minLength={12} required aria-invalid={Boolean(passwordState.fieldErrors?.confirmation)} />{passwordState.fieldErrors?.confirmation ? <small>{passwordState.fieldErrors.confirmation}</small> : null}</label>
          <div className="ops-settings-form-footer"><span>Use at least 12 characters. A recent login may be required.</span><button type="submit" disabled={passwordPending}><KeyRound aria-hidden="true" />{passwordPending ? "Updating…" : "Update password"}</button></div>
        </form>
        <FormMessage state={passwordState} />
        <div className="ops-settings-avatar-row">
          <ProfileAvatar fullName={staff.fullName} email={email} avatarUrl={staff.avatarUrl} size="sm" />
          <div><strong>Current session</strong><small>{email || "Verified Supabase account"}</small></div>
          <form action={signOutAction}><SignOutButton /></form>
        </div>
      </section>
    </>
  );
}
